// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    bytes32 PROPOSER = keccak256("PROPOSER_ROLE");

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(address actor, address victim) public {
        vm.assume(actor != address(0));
        vm.assume(victim != address(0));
        vm.assume(actor != address(this));

        // both actor and victim hold PROPOSER_ROLE
        c.grantRole(PROPOSER, actor);
        c.grantRole(PROPOSER, victim);
        assertTrue(c.hasRole(PROPOSER, victim));

        vm.prank(actor);
        bool ok;
        try c.renounceRole(PROPOSER, victim) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful renounce by A may only remove A's own role;
        // a distinct victim's membership must survive.
        assertTrue(!ok || victim == actor || c.hasRole(PROPOSER, victim));
    }
}
